if(def.sharedPrefix){const live=(await sharedRows())[0];await sharedDb.delete(live.id);for(let i=0;i<17;i++)await sharedDb.table.add([{...live,id:`99999999-9999-4999-8999-${String(i).padStart(12,'0')}`,status:'deleted'}]);await sharedDb.table.add([live]);}
const initialSharedRows=await sharedRows();
