function normalize(value){let text=JSON.stringify(value).replaceAll(work,'<work>');for(const [index,row] of finalSharedRows.entries()){text=text.replaceAll(row.id,`88888888-8888-4888-8888-${888888888888+index}`);if(row.shareIdempotencyKey)text=text.replaceAll(row.shareIdempotencyKey,'<workspace-share-key>');if(row.shareProvenance){const hash=JSON.parse(row.shareProvenance).targetPrincipalHash;if(hash)text=text.replaceAll(hash,'<workspace-principal-hash>');}}for(const h of hashes)text=text.replaceAll(h,'<workspace-binding-hash>');const out=JSON.parse(text);for(const key of ['initialFiles','files'])out[key]=Object.fromEntries(Object.entries(out[key]).sort(([a],[b])=>a.localeCompare(b)));return out;}
